use crate::aap::caps::{http_client, state_read};

struct Node;

const STORE_KEY: &str = "subscriptions";
const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push_str(&format!("{:02X}", b));
            }
        }
    }
    out
}

/// Minimal parser for a JSON array of strings. Returns None if the text is not
/// such an array.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            ',' => continue,
            '"' => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            '"' => cur.push('"'),
                            '\\' => cur.push('\\'),
                            '/' => cur.push('/'),
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            }
                            _ => return None,
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
            }
            _ => return None,
        }
    }
    Some(out)
}

fn parse_subscriptions(raw: &str) -> Vec<String> {
    let candidates: Vec<String> = match parse_json_string_array(raw) {
        Some(v) => v,
        None => raw.lines().map(|l| l.to_string()).collect(),
    };
    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let t = c.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        if !urls.iter().any(|u| u == t) {
            urls.push(t.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Approved enrichment fetch. Its result is deliberately unused so the
        // node's output is unchanged; transport failures are returned as values
        // and ignored.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
        let _ = http_client::fetch(&url);

        let urls = match state_read::get(STORE_KEY) {
            Some(raw) => parse_subscriptions(&raw),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

